<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ubuntu Desktop</title>
<style>
  * { box-sizing: border-box; }
  :root {
    --panel: rgba(25, 25, 32, .92);
    --window: #292932;
    --window-light: #353540;
    --text: #f4f4f7;
    --muted: #b7b6c1;
    --accent: #e95420;
    --border: rgba(255,255,255,.12);
  }
  body {
    margin: 0;
    min-width: 720px;
    min-height: 500px;
    overflow: hidden;
    font: 14px/1.35 Arial, sans-serif;
    color: var(--text);
    background: #24152f;
  }
  #desktop {
    width: 100vw;
    height: 100vh;
    position: relative;
    overflow: hidden;
    background:
      radial-gradient(circle at 78% 16%, rgba(242, 110, 70, .62), transparent 27%),
      radial-gradient(ellipse at 12% 90%, rgba(98, 38, 130, .8), transparent 48%),
      linear-gradient(135deg, #191324 0%, #4a224d 43%, #e54d32 100%);
  }
  #desktop::after {
    content: "";
    position: absolute;
    inset: 32px 0 0;
    pointer-events: none;
    opacity: .15;
    background: repeating-linear-gradient(125deg, transparent 0 55px, rgba(255,255,255,.18) 56px 58px, transparent 59px 120px);
  }
  #topbar {
    position: absolute;
    z-index: 20;
    top: 0;
    left: 0;
    right: 0;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 13px;
    background: rgba(20, 18, 25, .9);
    color: #eee;
    font-size: 13px;
  }
  #topbar strong { font-size: 14px; }
  .top-status { letter-spacing: .2px; color: #ddd; }
  #taskbar {
    position: absolute;
    z-index: 20;
    left: 0;
    top: 32px;
    bottom: 0;
    width: 66px;
    padding: 12px 8px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    align-items: center;
    background: rgba(25, 23, 31, .77);
    border-right: 1px solid rgba(255,255,255,.08);
  }
  .launcher {
    width: 50px;
    height: 50px;
    border: 0;
    border-radius: 12px;
    cursor: pointer;
    color: white;
    font-weight: bold;
    font-size: 11px;
    transition: transform .15s, background .15s;
    box-shadow: 0 4px 12px rgba(0,0,0,.22);
  }
  .launcher:hover { transform: scale(1.08); }
  #open-files { background: linear-gradient(135deg, #f4b526, #dd7615); }
  #open-notepad { background: linear-gradient(135deg, #4b9ce2, #2763af); }
  .window {
    position: absolute;
    z-index: 5;
    width: 620px;
    height: 440px;
    min-width: 360px;
    min-height: 240px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: var(--window);
    box-shadow: 0 20px 50px rgba(0,0,0,.48);
    resize: both;
  }
  #files-window { top: 74px; left: 100px; }
  #notepad-window { top: 128px; left: 215px; }
  .titlebar {
    height: 39px;
    min-height: 39px;
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 0 10px 0 14px;
    background: linear-gradient(#3a3a45, #30303a);
    border-bottom: 1px solid var(--border);
    cursor: move;
    user-select: none;
  }
  .app-mark {
    width: 18px;
    height: 18px;
    display: grid;
    place-items: center;
    border-radius: 4px;
    font-size: 12px;
  }
  .file-mark { background: #e99b18; }
  .note-mark { background: #3687d3; }
  .titlebar h2 {
    margin: 0;
    flex: 1;
    font-size: 14px;
    font-weight: normal;
  }
  .win-close {
    width: 24px;
    height: 24px;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: #eee;
    cursor: pointer;
    font-size: 19px;
    line-height: 20px;
  }
  .win-close:hover { background: #d84835; }
  .files-toolbar {
    min-height: 46px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 11px;
    background: #24242c;
    border-bottom: 1px solid var(--border);
  }
  #files-up, #new-tab {
    border: 1px solid var(--border);
    background: #454550;
    color: white;
    border-radius: 5px;
    cursor: pointer;
  }
  #files-up {
    width: 30px;
    height: 29px;
    font-size: 18px;
  }
  #files-up:hover, #new-tab:hover { background: #5a5a68; }
  #files-up:disabled { opacity: .4; cursor: default; }
  #files-path {
    flex: 1;
    padding: 6px 9px;
    overflow: hidden;
    border-radius: 5px;
    background: #15151b;
    color: #f2c8b8;
    font-family: Consolas, monospace;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  #files-list {
    flex: 1;
    min-height: 0;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(115px, 1fr));
    align-content: start;
    gap: 9px;
    padding: 15px;
    overflow: auto;
    background: #2d2d36;
  }
  .fs-item {
    min-height: 82px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 7px;
    padding: 7px;
    overflow: hidden;
    border: 1px solid transparent;
    border-radius: 7px;
    cursor: default;
    text-align: center;
    color: #f7f7f9;
    word-break: break-word;
  }
  .fs-item:hover { background: #41414d; border-color: #676778; }
  .fs-item .icon { font-size: 32px; line-height: 1; }
  .fs-item.file .icon { color: #8ac4ff; }
  .files-status {
    min-height: 27px;
    padding: 6px 12px;
    color: var(--muted);
    background: #25252d;
    border-top: 1px solid var(--border);
    font-size: 12px;
  }
  .notepad-body {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    background: #24242c;
  }
  .tabs-row {
    min-height: 41px;
    display: flex;
    align-items: stretch;
    border-bottom: 1px solid var(--border);
    overflow: hidden;
  }
  #tabs {
    flex: 1;
    display: flex;
    min-width: 0;
    overflow-x: auto;
  }
  .tab {
    max-width: 160px;
    min-width: 105px;
    display: flex;
    align-items: center;
    padding: 0 12px;
    overflow: hidden;
    border-right: 1px solid var(--border);
    background: #30303a;
    color: #bdbdc8;
    cursor: pointer;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  .tab:hover { background: #3b3b47; }
  .tab.active { background: #202027; color: white; box-shadow: inset 0 3px var(--accent); }
  #new-tab {
    width: 40px;
    margin: 6px 8px;
    font-size: 21px;
    line-height: 20px;
  }
  #editor {
    width: 100%;
    flex: 1;
    min-height: 0;
    resize: none;
    border: 0;
    outline: 0;
    padding: 17px;
    background: #202027;
    color: #f2f2f3;
    font: 15px/1.55 Consolas, "Courier New", monospace;
  }
</style>
</head>
<body>
<div id="desktop">
  <header id="topbar">
    <strong>Activities</strong>
    <span>Ubuntu Desktop</span>
    <span class="top-status">⌁ &nbsp; ◉ &nbsp; 10:42</span>
  </header>

  <nav id="taskbar" aria-label="Application dock">
    <button id="open-files" class="launcher" type="button" aria-label="Open Files">📁<br>Files</button>
    <button id="open-notepad" class="launcher" type="button" aria-label="Open Notepad">📝<br>Notes</button>
  </nav>

  <section id="files-window" class="window" aria-label="Files window">
    <div class="titlebar">
      <span class="app-mark file-mark">▰</span><h2>Files</h2>
      <button class="win-close" type="button" aria-label="Close Files">×</button>
    </div>
    <div class="files-toolbar">
      <button id="files-up" type="button" aria-label="Go to parent folder">←</button>
      <div id="files-path">/</div>
    </div>
    <main id="files-list" aria-label="Filesystem listing"></main>
    <div id="files-status" class="files-status"></div>
  </section>

  <section id="notepad-window" class="window" aria-label="Notepad window">
    <div class="titlebar">
      <span class="app-mark note-mark">▤</span><h2>Notepad</h2>
      <button class="win-close" type="button" aria-label="Close Notepad">×</button>
    </div>
    <div class="notepad-body">
      <div class="tabs-row"><div id="tabs" role="tablist"></div><button id="new-tab" type="button" aria-label="New tab">+</button></div>
      <textarea id="editor" aria-label="Text editor" spellcheck="true"></textarea>
    </div>
  </section>
</div>

<script>
(() => {
  const filesystem = {
    "/": {
      bin: { type: "folder", children: { bash: { type: "file" }, ls: { type: "file" }, python: { type: "file" } } },
      etc: { type: "folder", children: { hosts: { type: "file" }, passwd: { type: "file" }, "network.conf": { type: "file" } } },
      home: { type: "folder", children: {
        user: { type: "folder", children: {
          Documents: { type: "folder", children: { "welcome.txt": { type: "file" }, "project-notes.md": { type: "file" } } },
          Downloads: { type: "folder", children: { "ubuntu-wallpaper.jpg": { type: "file" }, "archive.zip": { type: "file" } } },
          Pictures: { type: "folder", children: { "sunset.png": { type: "file" }, "profile.jpg": { type: "file" } } },
          "README.txt": { type: "file" }
        }}
      }},
      usr: { type: "folder", children: { bin: { type: "folder", children: {} }, share: { type: "folder", children: {} } } },
      var: { type: "folder", children: { log: { type: "folder", children: { "system.log": { type: "file" } } }, tmp: { type: "folder", children: {} } } }
    }
  };

  const filesWindow = document.getElementById("files-window");
  const notepadWindow = document.getElementById("notepad-window");
  const filesList = document.getElementById("files-list");
  const filesPath = document.getElementById("files-path");
  const filesUp = document.getElementById("files-up");
  let currentPath = "/";

  function directoryAt(path) {
    if (path === "/") return filesystem["/"];
    let node = filesystem["/"];
    for (const part of path.split("/").filter(Boolean)) node = node[part].children;
    return node;
  }

  function renderFiles() {
    const entries = directoryAt(currentPath);
    filesPath.textContent = currentPath;
    filesUp.disabled = currentPath === "/";
    filesList.innerHTML = "";
    Object.entries(entries).sort((a, b) => {
      if (a[1].type !== b[1].type) return a[1].type === "folder" ? -1 : 1;
      return a[0].localeCompare(b[0]);
    }).forEach(([name, entry]) => {
      const item = document.createElement("div");
      item.className = "fs-item " + entry.type;
      item.innerHTML = `<span class="icon">${entry.type === "folder" ? "📁" : "📄"}</span><span>${name}</span>`;
      if (entry.type === "folder") {
        item.title = "Double-click to open " + name;
        item.addEventListener("dblclick", () => {
          currentPath = currentPath === "/" ? "/" + name : currentPath + "/" + name;
          renderFiles();
        });
      }
      filesList.appendChild(item);
    });
    document.getElementById("files-status").textContent =
      `${Object.keys(entries).length} item${Object.keys(entries).length === 1 ? "" : "s"} · Double-click folders to open`;
  }

  filesUp.addEventListener("click", () => {
    if (currentPath !== "/") {
      const parts = currentPath.split("/").filter(Boolean);
      parts.pop();
      currentPath = parts.length ? "/" + parts.join("/") : "/";
      renderFiles();
    }
  });

  document.getElementById("open-files").addEventListener("click", () => {
    filesWindow.style.display = "flex";
    bringToFront(filesWindow);
  });
  document.getElementById("open-notepad").addEventListener("click", () => {
    notepadWindow.style.display = "flex";
    bringToFront(notepadWindow);
  });
  document.querySelectorAll(".window .win-close").forEach(button => {
    button.addEventListener("click", () => button.closest(".window").style.display = "none");
  });

  let highestZ = 5;
  function bringToFront(windowElement) {
    windowElement.style.zIndex = ++highestZ;
  }
  document.querySelectorAll(".window").forEach(windowElement => {
    windowElement.addEventListener("mousedown", () => bringToFront(windowElement));
  });

  document.querySelectorAll(".titlebar").forEach(bar => {
    bar.addEventListener("mousedown", event => {
      if (event.target.closest("button")) return;
      const win = bar.closest(".window");
      bringToFront(win);
      const startX = event.clientX, startY = event.clientY;
      const startLeft = win.offsetLeft, startTop = win.offsetTop;
      function move(e) {
        win.style.left = Math.max(66, startLeft + e.clientX - startX) + "px";
        win.style.top = Math.max(32, startTop + e.clientY - startY) + "px";
      }
      function stop() {
        document.removeEventListener("mousemove", move);
        document.removeEventListener("mouseup", stop);
      }
      document.addEventListener("mousemove", move);
      document.addEventListener("mouseup", stop);
    });
  });

  const storageKey = "ubuntu-desktop-notepad-tabs-v1";
  const tabsElement = document.getElementById("tabs");
  const editor = document.getElementById("editor");
  let tabs;
  let activeTabId;

  function loadTabs() {
    try {
      const saved = JSON.parse(localStorage.getItem(storageKey));
      if (saved && Array.isArray(saved.tabs) && saved.tabs.length) {
        tabs = saved.tabs;
        activeTabId = saved.activeTabId && tabs.some(tab => tab.id === saved.activeTabId)
          ? saved.activeTabId : tabs[0].id;
        return;
      }
    } catch (_) {}
    tabs = [{ id: "tab-" + Date.now(), title: "Untitled 1", content: "" }];
    activeTabId = tabs[0].id;
  }
  function saveTabs() {
    localStorage.setItem(storageKey, JSON.stringify({ tabs, activeTabId }));
  }
  function activeTab() {
    return tabs.find(tab => tab.id === activeTabId);
  }
  function renderTabs() {
    tabsElement.innerHTML = "";
    tabs.forEach(tab => {
      const element = document.createElement("div");
      element.className = "tab" + (tab.id === activeTabId ? " active" : "");
      element.textContent = tab.title;
      element.title = tab.title;
      element.setAttribute("role", "tab");
      element.setAttribute("aria-selected", String(tab.id === activeTabId));
      element.addEventListener("click", () => {
        activeTabId = tab.id;
        renderTabs();
        editor.value = tab.content;
        saveTabs();
        editor.focus();
      });
      tabsElement.appendChild(element);
    });
    editor.value = activeTab().content;
  }
  document.getElementById("new-tab").addEventListener("click", () => {
    const number = tabs.length + 1;
    const tab = { id: "tab-" + Date.now() + "-" + Math.random(), title: "Untitled " + number, content: "" };
    tabs.push(tab);
    activeTabId = tab.id;
    saveTabs();
    renderTabs();
    editor.focus();
  });
  editor.addEventListener("input", () => {
    activeTab().content = editor.value;
    saveTabs();
  });

  loadTabs();
  renderTabs();
  renderFiles();
})();
</script>
</body>
</html>
